/** Machine translated draft; religious and linguistic review pending. */
internal object DuaAmDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("ዶሮ ወይም አህያ መስማት", "አላህ ሆይ ከችሮታህ (ዶሮ) እጠይቅሃለሁ። - ከተረገመው ሸይጣን (አህያ) በአላህ እጠበቃለሁ።", "ዶሮ በሰማ ጊዜ የአላህን ችሮታ ለምነው። የአህያ ጩኸት ሲሰማ ከሰይጣን ተሸሸግ።", "ዶሮ መልአክን አየች አህያይቱም ሰይጣንን አየች።"),
        "dua_something_liked" to DuaText("የሚደነቅ ነገር ማየት (በክፉ ዓይን ላይ)", "አላህ የሻውን። አላህ ሆይ ባርከው።", "የአንድ ሰው የሆነ አስደናቂ ነገር ሲመለከቱ፣ ለበረከት ጸልዩ።", "ለበረከት መጸለይ ከክፉ ዓይን ይከላከላል."),
        "dua_sell_buy_debt_repaid" to DuaText("ዕዳ ሲከፍሉ", "አላህ ከነቤተሰብህ እና ሀብተህ ይባርክህ።", "ዕዳ ሲከፍል ለአበዳሪው.", "የብድር መመለሻ ምስጋና እና ክፍያ ነው."),
        "dua_talbiyah" to DuaText("ጥልቢያ", "እነሆ እኔ አላህ ሆይ እነሆ እኔ ነኝ። እነሆ እኔ፣ አጋር የለህም፣ እዚህ ነኝ። ምሥጋና፣ በረከቶችና ሥልጣን ሁሉ የአንተ ናቸው። አጋር የለህም።", "ኢህራም ከገባ በኋላ ጮክ ብሎ።", "የሐጅ እና ዑምራ አርማ።"),
        "dua_yamani_hajar" to DuaText("በሩክን ያማኒ እና በሃጀር አስዋድ መካከል", "ጌታችን ሆይ በዱንያ መልካምን በመጨረሻይቱም ዓለም መልካም ነገርን ስጠን ከእሳትም ቅጣት ጠብቀን።", "በጧፍ፣ በየመን ጥግ እና በጥቁር ድንጋይ መካከል።", "ነብዩ ﷺ ይህን በጧፍ በዚህ ቦታ አንብበውታል።"),
        "dua_safa_marwa" to DuaText("በሳፋ እና ማርዋ ላይ", "ሊመለክ የሚገባው አላህ ብቻ ነው፣ እርሱ ብቻውን ነው፣ አጋር የለውም። ንግሥናው የርሱ ብቻ ነው፤ ምስጋናም የርሱ ብቻ ነው። እርሱም በነገሩ ሁሉ ላይ ቻይ ነው። ሊመለክ የሚገባው አላህ ብቻ ነው። የገባውን ቃል ፈጸመ፣ አገልጋዩን ረድቶ ብቻውን ኮንፌዴሬሽኖችን አሸነፈ።", "ወደ ሳፋ መውጣት እና ወደ ቂብላ (ሶስት ጊዜ) መጋጠም.", "የነብዩ ዚክር ﷺ በሶፋ እና መርዋ ላይ።"),
        "dua_arafah" to DuaText("የአረፋ ቀን ምርጥ ዱዓ", "ሊመለክ የሚገባው አላህ ብቻ ነው፣ እርሱ ብቻውን ነው፣ አጋር የለውም። ንግሥናው የርሱ ብቻ ነው፤ ምስጋናም የርሱ ብቻ ነው። እርሱም በነገሩ ሁሉ ላይ ቻይ ነው።", "የአረፋ ቀን - ምርጥ ዱዓ።", "በላጩ ዱዓ የዐረፋ ቀን ዱዓ ሲሆን በላጩ ቃላቶችም እነዚህ ናቸው።"),
        "dua_takbeer_tashreeq" to DuaText("ተክቢር-ኢ-ታሽሪቅ", "አሏህ ታላቅ ነው አሏህ ታላቅ ነው። ከአላህ በስተቀር ሌላ አምላክ የለም። አላህ ታላቅ ነው፡ አላህም ታላቅ ነው፡ ምስጋናም ሁሉ ለአላህ ነው።", "ከእያንዳንዱ የግዴታ ሶላት በኋላ ከፈጅር 9 ዙል-ሂጃህ እስከ 13 ዙልሂጃህ አስሩ።", "ከዓልይ እና ኢብኑ መስዑድ (RA) - ዋጅብ በሐነፊዎች የተዘገበ።"),
        "dua_zamzam" to DuaText("ዛምዛም መጠጣት", "አላህ ሆይ ጠቃሚ እውቀትን፣ የተትረፈረፈ ሲሳይንና ከበሽታ ሁሉ መድሀኒት እለምንሃለሁ።", "ዘምዘምን ስትጠጡ ለምትፈልጉት ሁሉ ዱዓ አድርጉ።", "ዘምዘም ለተሰከረው ለማንኛውም ነገር ነው (ኢብኑ ማጃህ 3062)።"),
        "dua_q_ma_khalaqta_batila" to DuaText("በፍጥረት ላይ ማሰላሰል", "Our Lord, You did not create all this in vain. ክብር ላንተ ይሁን ከእሳትም ቅጣት ጠብቀን።", "የሰማያትንና የምድርን አፈጣጠር የሚያንፀባርቁ ሰዎች ዱዓ።", "የአስተዋይ ሰዎች ዱዓ (ኡሉል-አልባብ)።"),
        "dua_q_sami_na_munadiyan" to DuaText("የእምነት ጠሪውን ሰምተናል", "ጌታችን ሆይ አንድ ጠሪ በጌታህ እመኑ እያለ ወደ እምነት ሲጠራ ሰምተነዋል አመንንም። ጌታችን ሆይ ኃጢያታችንን ይቅር በለን ጥፋታችንንም ከእኛ አርቅ ከጻድቃን ጋር ግደለን።", "በጻድቃን መካከል የእምነት እና የመሞት ዱዓ።", "የይቅርታና መልካም ፍጻሜ ዱዓ።"),
        "dua_q_atina_ma_waadtana" to DuaText("ቃል የገባህውን ስጠን", "ጌታችን ሆይ! በመልክተኞችህ ቃል የገባህልንን ስጠን። በትንሣኤም ቀን አታዋርደን። በእርግጥም፣ ቃልህን አታፈርስም።", "በትንሣኤ ቀን ከውርደት መሸሽ።", "በመጨረሻው ዓለም ክብርን መፈለግ።"),
        "dua_q_israfana" to DuaText("የኛን ትርፍ ይቅር በለን።", "ጌታችን ሆይ ኀጢኣቶቻችንንና በጉዳዮቻችን ላይ መበደላችንን ማር።እግሮቻችንንም አጽናን በከሓዲዎችም ሕዝቦች ላይ እርዳን።", "የቀደምት ነብያት ባልደረቦች ዱዓ።", "የፅናት እና የይቅርታ ዱዓ።"),
        "dua_q_jamiun_nas" to DuaText("የሰውን ልጅ ትሰበስባለህ", "ጌታችን ሆይ! ሰውን በእርሱ ጥርጥር በሌለበት ቀን በእርግጥ ትሰበስባለች። አላህ ቃል ኪዳኑን አያፈርስም።", "በትንሣኤ ቀን እርግጠኝነትን የሚያረጋግጥ ነው።", "በእውቀት ላይ የጸኑ ሰዎች ዱዓ።"),
        "dua_q_maash_shahidin" to DuaText("ከምሥክሮቹ መካከል ጻፈልን።", "ጌታችን ሆይ! አምነናል፤ ከመስካሪዎችም ጻፍን።", "እውነትን የተገነዘቡ እና ያመኑ ሰዎች ዱዓ።", "እምነትን ለመቀበል ዱዓ።"),
        "dua_q_la_tajalna_zalimin" to DuaText("ከበደለኞች ጋር አይደለም።", "ጌታችን ሆይ ከበደለኞች ሰዎች ጋር አታድርገን።", "የአል-አዕራፍ ሰዎች ዱዓ።", "ከበዳዮች እጣ ፈንታ መሸሽ።"),
        "dua_q_tawaffana_muslimin" to DuaText("እንደ ሙስሊም ትግስት እና ሞት", "ጌታችን ሆይ በኛ ላይ ትዕግስትን አፍስሰን ሙስሊም ሆነን እንድንሞት አድርገን።", "ባመኑ ጊዜ የፈርዖን አስማተኞች ዱዓ።", "በፈተና ውስጥ መታገስ እና በእምነት ላይ መጨረሻ።"),
        "dua_q_la_tajalna_fitnah" to DuaText("ለጨቋኞች ፈተና አይደለም።", "በአላህ ላይ ተመካን። ጌታችን ሆይ በበደለኞች ሕዝቦች ላይ ፈተና አታድርገን።በእዝነትህም ከከሓዲዎች ሕዝቦች አድነን።", "የሙሳ ሰዎች ዱዓ (AS)።", "ከጨቋኞች እና ከጨቋኞች ለመታደግ ዱዓ።"),
        "dua_q_nuh_ma_laysa_li" to DuaText("የኑህ ዱዓ (AS) ለይቅርታ", "ጌታዬ ሆይ በርሱ ዕውቀት የሌለኝን ነገር ከመጠየቅ አንተን እጠበቃለሁ። ለእኔም ይቅርታ ካላደረግክና ካላዘንክልኝ እኔ ከከሳሪዎቹ እሆናለሁ።", "የነቢዩ ኑህ የንስሐ ዱዓ (AS)።", "በአግባብ የመጠየቅ ትምህርት።"),
        "dua_q_mudkhala_sidq" to DuaText("የእውነት መግቢያ እና መውጫ", "ጌታዬ ሆይ በእውነት አስገባኝ በእውነትም ውጣ።ከራስህም ዘንድ ረዳት ስልጣንን ስጠኝ።", "አዲስ ተግባር፣ ቤት ወይም ቦታ ከመግባትዎ በፊት።", "ዱዓው ለነቢዩ ﷺ በሂጅራ ጊዜ አስተማረ።"),
        "dua_q_la_tadharni_fardan" to DuaText("የዝካሪያ ዱዓ (AS) - ብቻዬን አትተወኝ።", "ጌታዬ ሆይ እኔን ብቻዬን አትተወኝ አንተም ከወራሾች ሁሉ በላጭ ነህ።", "ልጆች ለሚፈልጉ.", "በዚህ ዱዓ አላህ ለያህያ (AS) ሰጠው።"),
        "dua_q_munzalan_mubarakan" to DuaText("የተባረከ ማረፊያ ቦታ", "ጌታዬ ሆይ፣ በተባረከ ማረፊያ ላይ ላርፍ፣ እና አንተ ወደ ምድር ከሚያመጡት ሁሉ በላጭ ነህ።", "ወደ አዲስ ቤት ሲሄዱ ወይም የሆነ ቦታ ሲያቆሙ - የኑህ (AS) ዱአ።", "በአዲስ ቦታ ለመባረክ ዱዓ።"),
        "dua_q_amanna_faghfir" to DuaText("እናምናለን፣ስለዚህም ይቅር በለን።", "ጌታችን ሆይ አምነናልና ይቅር በለን ማረንም አንተም ከአዛኞች ሁሉ በላጭ ነህ።", "የአላህ መልካም ባሮች ዱዓ።", "አጠቃላይ የይቅርታ እና የምህረት ዱዓ።"),
        "dua_q_isrif_jahannam" to DuaText("የገሃነምን ቅጣት አስወግድ", "ጌታችን ሆይ የገሀነምን ቅጣት ከእኛ ላይ ቀይርልን። ቅጣቷ ዘውታሪ ነውና። በእርግጥ መጥፎ መኖሪያ እና መኖሪያ ነው.", "የረህማን ባሪያዎች ዱዓ (ኢባድ አር-ረህማን)።", "ከጀሀነም መሸሸጊያ የቁርዓን ዱዓ።"),
        "dua_q_hab_li_hukman" to DuaText("የኢብራሂም ዱዓ (AS) - ጥበብ እና ጀና", "ጌታዬ ሆይ ጥበብን ስጠኝ ከጻድቃንም ጋር ተባበረኝ በኋለኞቹም ትውልዶች ዘንድ ክብርን ስጠኝ የገነትንም ወራሾች አድርገኝ።", "ጥበብን በመጠየቅ የጻድቃን እና የጀነት ማኅበር።", "የኢብራሂም አጠቃላይ ዱዓ (AS)።"),
        "dua_q_lut_najjini_ahli" to DuaText("የሉጥ ዱአ (AS) - ቤተሰቤን አድን", "ጌታዬ ሆይ እኔንም ቤተሰቤንም ከሚሠሩት (ከፍጻሜው) አድን።", "ቤተሰብን ከክፉ አካባቢ መጠበቅ።", "ቤተሰብን ከክፉ መከላከል."),
        "dua_q_sulaiman_awzini" to DuaText("የሱለይማን ዱዓ (AS) ለምስጋና", "ጌታዬ ሆይ በእኔና በወላጆቼ ላይ የለገስከውን ውለታ እንዳመሰግን አንተን ደስ የሚያሰኘውን መልካም ሥራ እንድሠራ አስረገኝ።በእዝነትህም ባሮችህ መካከል አስገባኝ።", "ለበረከት አመስጋኝ የመሆን ችሎታ።", "የሱለይማን የምስጋና ዱአ (AS)።"),
        "dua_q_musa_zalamtu" to DuaText("የሙሳ ዱዓ (AS) - ራሴን ተሳሳትኩ።", "ጌታዬ ሆይ ራሴን በድያለሁና ይቅርታ አድርግልኝ።", "ከስህተት በኋላ ወዲያውኑ ንስሐ መግባት.", "አላህ ሙሳን (AS) ይቅር ብሎታል።"),
        "dua_q_musa_najjini" to DuaText("የሙሳ ዱዓ (AS) - ከጨቋኞች አድነኝ።", "ጌታዬ ሆይ ከበደለኞች ሰዎች አድነኝ።", "ጨቋኞችን ሲፈሩ።", "ከግብፅ ሲወጡ የሙሳ ዱአ (AS)።"),
        "dua_q_lut_unsurni" to DuaText("የሉጥ ዱአ (AS) - በሙስና ላይ እገዛ", "ጌታዬ ሆይ! በአጥፊዎቹ ሕዝቦች ላይ እርዳኝ።", "ሙስናን በሚያሰራጩት ላይ እርዳታ ለማግኘት።", "በእውነት ላይ የቆሙ ሰዎች ዱዓ።"),
        "dua_q_hab_li_salihin" to DuaText("የኢብራሂም ዱዓ (AS) ለፃድቅ ልጅ", "ጌታዬ ሆይ ከመልካሞቹ (ሕፃን) ስጠኝ።", "ጻድቅ ልጆችን መጠየቅ።", "በዚህ ዱዓ ኢስማኢል (AS) ተሰጥቷል።"),
        "dua_q_wasita_kulla_shay" to DuaText("ዙፋን የተሸከሙ የመላእክት ዱዓ", "ጌታችን ሆይ አንተ ነገሩን ሁሉ በእዝነት እና በእውቀት ያከበብሃልና የተጸጸተህንና መንገድህን የተከተለውን ይቅር በላቸው ከገሀነም ቅጣት ጠብቃቸው።", "ዐርሹን የተሸከሙ መላእክት ለምእመናን ይህን ዱዓ ያደርጋሉ።", "በመላዕክት ዱዓ ውስጥ ለመካተት በማሰብ የተነበበ።"),
        "dua_q_ikhwanina" to DuaText("ከእኛ በፊት ለነበሩት ወንድሞቻችን", "ጌታችን ሆይ እኛንም በእምነትም ከእኛ በፊት ለነበሩት ወንድሞቻችን ማረን በልቦቻችንም ውስጥ በአመኑት ላይ ቂምን አታድርግ። ጌታችን ሆይ አንተ በእርግጥ ቸር አዛኝ ነህ።", "ዱዓ ለቀደሙት አማኞች እና ለንፁህ ልብ።", "(RA) ለክቡር ሰሀቦች እና ቀደምት አማኞች ዱዓ።"),
        "dua_q_alayka_tawakkalna" to DuaText("በአንተ ላይ እንመካለን (ኢብራሂም ዐ.ሰ)", "ጌታችን ሆይ በአንተ ላይ ተመኪ ነን ወደ አንተ ተመለስን መመለሻም ወደ አንተ ብቻ ነው። ጌታችን ሆይ! ለከሓዲዎች ፈተና አታድርገንና ማረን። ጌታችን ሆይ አንተ አሸናፊው ጥበበኛው ነህ።", "የኢብራሂም (AS) እና የባልደረቦቻቸው ዱአ።", "በአላህ ላይ የመመካት እና ወደርሱ የመመለስ ዱዓ።"),
        "dua_q_atmim_nurana" to DuaText("ፍፁም ብርሃናችን", "ጌታችን ሆይ ብርሃናችንን ሞላልን ይቅር በለን። አንተ በነገሩ ሁሉ ላይ ቻይ ነህና።", "በትንሳኤ ቀን የምእመናን ዱዓ።", "በሲራቱ ላይ ብርሃን መጠየቅ."),
        "dua_q_asiya_baytan" to DuaText("የአሲያ ዱአ - በጃና ውስጥ ያለ ቤት", "ጌታዬ ሆይ! በአጠገብህ በገነት ውስጥ ቤትን ገንባ። ከፈርዖንና ከሥራውም አድነኝ፤ ከበደለኞችም ሕዝቦች አድነኝ።", "የአሲያ ዱዓ የፈርዖን ሚስት።", "አላህ ለምእመናን አርአያ አደረጋት።"),
        "dua_adhan_response" to DuaText("ለአድሃን ምላሽ መስጠት", "ከአላህ ጋር ካልሆነ በስተቀር ምንም ሃይል እና ሃይል የለም።", "ሙአዚኑ የሚናገረውን ይድገሙት; 'ሀያ አላስ-ሳላህ' እና 'ሀያ አላል-ፈላህ' ላይ እንዲህ ይበሉ።", "ከልቡ የመለሰ ጀነት ይገባል።"),
        "dua_adhan_shahadah" to DuaText("ከሙአዚን ሻሃዳህ በኋላ", "እኔም እመሰክራለው ሊመለክ የሚገባው አላህ ብቻ እንደሆነ፣ ብቸኛ፣ አጋር የሌለው፣ ሙሐመድ ﷺ የሱ አገልጋይና መልክተኛ ነው። በአላህ ጌታ በሙሐመድ ﷺ በመልእክተኛ እና በእስልምና ሃይማኖት ተደስቻለሁ።", "የሙአዚኑን የእምነት ምስክርነት በመስማት ላይ።", "ኃጢአቱ ተሰርዮለታል።"),
        "dua_istiftah_baid" to DuaText("የመክፈቻ ዱዓ፡- ከሀጢያት አርቀኝ።", "አሏህ ሆይ ምስራቅን ከምእራብ እንዳራቅክ ከኃጢአቴ አርቀኝ። አሏህ ሆይ ነጭ ልብስ ከቆሻሻ እንደሚጸዳ ከሀጢያት አንፃኝ። አላህ ሆይ ወንጀሎቼን በውሃ፣በበረዶ እና በበረዶ እጠበኝ።", "ከመክፈቻው ተክቢር በኋላ (በሳና ምትክም ሊባል ይችላል)።", "ነብዩ ﷺ ይህን በተክቢር እና በንባብ መካከል አነበቡት።"),
        "dua_hamdan_kathiran" to DuaText("ከሩኩ በኋላ የተትረፈረፈ ምስጋና", "ጌታችን ሆይ ፣ ምስጋና ላንተ ይገባል - ብዙ ፣ ንፁህ እና የተባረከ ምስጋና።", "ከሩኩ ከተነሳ በኋላ፣ ከ‘ራባና ላካል-ሃምድ’ ጋር።", "ከሰላሳ በላይ መላዕክት ለመመዝገብ ቀዳሚ ለመሆን ይሽቀዳደሙ ነበር።"),
    )
}
